import "server-only";
import { randomUUID } from "node:crypto";
import { PutObjectCommand, S3Client } from "@aws-sdk/client-s3";

// S3-compatible storage (AWS S3, Cloudflare R2, MinIO, ...).
export const MAX_IMAGE_BYTES = 5 * 1024 * 1024;

// Allow-list by MIME type; the extension is derived from this, never from the
// user-supplied filename. SVG is deliberately excluded (can carry scripts).
const IMAGE_TYPES: Record<string, string> = {
  "image/png": "png",
  "image/jpeg": "jpg",
  "image/webp": "webp",
  "image/gif": "gif",
};

let client: S3Client | undefined;

function env(name: string): string {
  const v = process.env[name];
  if (!v) throw new Error(`Missing env var ${name}`);
  return v;
}

function getClient(): S3Client {
  client ??= new S3Client({
    region: process.env.S3_REGION ?? "auto",
    endpoint: process.env.S3_ENDPOINT || undefined,
    credentials: {
      accessKeyId: env("S3_ACCESS_KEY_ID"),
      secretAccessKey: env("S3_SECRET_ACCESS_KEY"),
    },
  });
  return client;
}

export class UploadError extends Error {}

/** Validates and uploads an image, returning its public URL. */
export async function uploadImage(file: File, prefix: string): Promise<string> {
  const ext = IMAGE_TYPES[file.type];
  if (!ext) throw new UploadError("Only PNG, JPEG, WebP or GIF images are allowed.");
  if (file.size > MAX_IMAGE_BYTES) throw new UploadError("Image must be 5MB or smaller.");

  const key = `${prefix}/${randomUUID()}.${ext}`;
  await getClient().send(
    new PutObjectCommand({
      Bucket: env("S3_BUCKET"),
      Key: key,
      Body: Buffer.from(await file.arrayBuffer()),
      ContentType: file.type,
      CacheControl: "public, max-age=31536000, immutable",
    }),
  );
  return `${env("S3_PUBLIC_URL").replace(/\/$/, "")}/${key}`;
}
EOF
